// ─── The kit as one object, for pages/BookKit.jsx ─────────────────────────
//
// The same shape as data/kit-ia-no-atendimento-e-nas-vendas.js: the parts
// every kit has and `bands`, the sections only this book has, in order,
// between the templates and the exercises, with the names o-kit.md promises.
// Icons are named, and must be in ICONS of BookKit. The bands alternate gray
// and white, starting gray after the templates (white) and ending white
// before the exercises (gray): `alternate` sets them, and the count is even.

const steps = (items, icons) => items.map((item, index) => ({ ...item, icon: icons[index] }))
const criteria = items => items.map(item => ({ criterion: item.title, value: item.text, ...(item.links?.length ? { links: item.links } : {}) }))
const alternate = bands => bands.map((band, index) => ({ ...band, background: index % 2 === 0 ? 'gray' : 'white' }))

